// Deterministic checks on the RAG Agent output (the LLM's self-reporting is not trusted)
const item = $input.first().json;
const out = item.output;
const steps = item.intermediateSteps || [];

// 1. Real tool calls, and the text of every chunk actually returned by the tool
const toolCalls = steps.filter(s => s.action && s.action.tool === 'search_knowledge_base');
const chunkText = {};
for (const s of toolCalls) {
  const obs = typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation);
  try {
    const parsed = JSON.parse(obs);
    for (const resp of (Array.isArray(parsed) ? parsed : [parsed])) {
      for (const r of resp.results || []) chunkText[r.chunk_id] = r.text;
    }
  } catch (e) {
    // fallback: ids only (text unknown -> number check cannot run for these)
    for (const m of obs.matchAll(/"chunk_id"\s*:\s*"([^"]+)"/g)) chunkText[m[1]] = chunkText[m[1]] ?? null;
  }
}

// Numbers as written, normalized: "1,5" == "1.5", "3 500" == "3500"
const numbers = txt => new Set(
  (String(txt).replace(/(\d)[\s\u00a0\u202f](?=\d{3}\b)/g, '$1').match(/\d+(?:[.,]\d+)?/g) || [])
    .map(n => n.replace(',', '.')));

// 2. Keep only facts whose chunk was received AND whose numbers all appear in that chunk
const removedCitations = [], removedNumbers = [];
for (const q of out.questions || []) {
  q.facts = (q.facts || []).filter(f => {
    if (!(f.chunk_id in chunkText)) {
      removedCitations.push({ question: q.question, chunk_id: f.chunk_id, fact: f.fact });
      return false;
    }
    const src = chunkText[f.chunk_id];
    if (src === null) return true;  // text unavailable: citation verified, numbers not checkable
    const inSource = numbers(src);
    const missing = [...numbers(f.fact)].filter(n => !inSource.has(n));
    if (missing.length) {
      removedNumbers.push({ question: q.question, chunk_id: f.chunk_id, fact: f.fact, numbers_not_in_source: missing });
      return false;
    }
    return true;
  });
  q.status = q.facts.length > 0 ? 'answered' : 'not_found';
}

// 3. Summary built from verified facts only (the LLM summary drifted in tests F3, F7)
const verifiedFacts = (out.questions || []).flatMap(q => q.facts.map(f => f.fact));
const answered = (out.questions || []).filter(q => q.status === 'answered').length;

return [{
  json: {
    questions: out.questions,
    summary_for_recommender: verifiedFacts.length > 0 ? verifiedFacts.join(' ') : out.summary_for_recommender,
    searches_made: toolCalls.length,   // measured, not self-reported
    validation: {
      tool_calls: toolCalls.length,
      questions: (out.questions || []).length,
      answered_questions: answered,
      one_search_per_question: toolCalls.length >= answered,
      queries_used: toolCalls.map(s => s.action.toolInput),
      retrieved_chunk_ids: Object.keys(chunkText),
      removed_invalid_citations: removedCitations,
      removed_number_mismatch: removedNumbers,
      llm_summary_discarded: verifiedFacts.length > 0 ? out.summary_for_recommender : null
    }
  }
}];
